import{At as e,Et as t,ft as n,ht as r,lt as i,mt as a,n as o}from"./chunks/framework.CK3_e0nb.js";var s=JSON.parse(`{"title":"窗前的老槐树","description":"书房的窗前有一棵老槐树，枝桠舒展，树冠遮盖了大半个庭院。每年初夏，洁白的槐花便成串成串地挂满枝头，满院飘香。 记忆里，祖母总会在这时候拿着长竿打下新鲜的槐花，洗净后拌上面粉蒸成槐花饭。那是童年里最朴实也最难以忘怀的清甜滋味。时光匆匆流转，许多老房子渐渐拆迁改造，唯独这棵老槐树依然静默地伫立在岁月里，","frontmatter":{"id":"2f010d","title":"窗前的老槐树","datetime":"2026-10-03 10:00:00","category":"散文","tags":["记忆","生活"]},"headers":[],"relativePath":"essays/2f010d.md","filePath":"essays/essay-03.md","lastUpdated":1792855556000}`),c={name:`essays/2f010d.md`};function l(o,s,c,l,u,d){let f=e(`PostMeta`);return t(),n(`div`,null,[s[0]||=i(`h1`,{id:`窗前的老槐树`,tabindex:`-1`},[a(`窗前的老槐树 `),i(`a`,{class:`header-anchor`,href:`#窗前的老槐树`,"aria-label":`Permalink to “窗前的老槐树”`},`​`)],-1),r(f),s[1]||=i(`p`,null,`书房的窗前有一棵老槐树，枝桠舒展，树冠遮盖了大半个庭院。每年初夏，洁白的槐花便成串成串地挂满枝头，满院飘香。`,-1),s[2]||=i(`p`,null,`记忆里，祖母总会在这时候拿着长竿打下新鲜的槐花，洗净后拌上面粉蒸成槐花饭。那是童年里最朴实也最难以忘怀的清甜滋味。时光匆匆流转，许多老房子渐渐拆迁改造，唯独这棵老槐树依然静默地伫立在岁月里，见证着春去秋来的轮回与人间的悲欢离合。每当我伏案倦怠时，抬眼望向树叶筛落的微光，内心便能重新觅得一份笃定与平静，仿佛时光从未走远，故人一直在身旁守护。`,-1)])}var u=o(c,[[`render`,l]]);export{s as __pageData,u as default};